import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.C3fpVp7C.js";const u=JSON.parse('{"title":"3. Conservative scope attenuation","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0003-conservative-attenuation.md","filePath":"adr/0003-conservative-attenuation.md","lastUpdated":1792160181000}'),o={name:"adr/0003-conservative-attenuation.md"};function r(i,e,c,d,l,h){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="_3-conservative-scope-attenuation" tabindex="-1">3. Conservative scope attenuation <a class="header-anchor" href="#_3-conservative-scope-attenuation" aria-label="Permalink to &quot;3. Conservative scope attenuation&quot;">​</a></h1><p>Status: accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>An agent can derive a token for a sub-agent. The service must guarantee the child never permits a request that its parent denies. Scopes use globs in resources and parameters, and an exact subset test for two glob patterns is expensive and easy to get wrong.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>A child scope set is accepted only when every child scope is covered by a single parent scope. The action pattern, resource glob and every parameter glob of the child must be subsets of the parent&#39;s, a child may add parameter constraints but never drop one, an amount limit must use the same currency and be no higher, and approval requirements carry over. The glob subset check is conservative: it may reject a few exotic pairs where containment does hold, and it never accepts a pair where it does not. The scope engine in <code>src/scope/</code> has no I/O.</p><p>Property-based tests with fast-check generate scopes and requests over small alphabets and assert that an accepted child set never allows a request that its parent set denies, across chains of attenuations. A scheduled Stryker run measures how well those tests catch changes to the engine.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Soundness does not depend on the glob check being complete.</li><li>Some valid narrowings are rejected. A caller can work around this by stating the child scope in the same shape as the parent&#39;s.</li><li>Children also expire no later than their parent, carry no more uses and sit at most 8 levels deep by default.</li></ul>',9)])])}const v=t(o,[["render",r]]);export{u as __pageData,v as default};
